sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
    var requestUser = request.pathParams.user_name;
    var requestQuery = request.queryParams.ni_query;

    var user = new GlideRecord('sys_user');
    user.get('user_name', requestUser);

    if (!user.user_name) {
        var apiError = new sn_ws_err.ServiceError();
        apiError.setStatus(542);
        apiError.setMessage("User not found");
        apiError.setDetail("No user record found for the user_name passed into the ni_info web service resource using the user_name path parameter.");

        response.setError(apiError);
        return;
    }

    var gr = new GlideAggregate('x_58872_needit_needit');
    gr.addAggregate('COUNT');
    gr.addQuery('u_requested_for', user.sys_id);
    //gr.addEncodedQuery(requestQuery);
    gr.query();

    if (gr.next()) {
        var record = parseInt(gr.getAggregate('COUNT'));
    }

    var body = {};
    body.count = record;
    body.user = {
        'User ID': user.sys_id,
        'User Name': user.user_name
    };

    response.setBody(body);



})(request, response);
